input.command:
go mod edit -module example.com/systool && mkdir -p cmd/systool internal/sys && cat > cmd/systool/main.go <<'EOF'
// Command systool is a CLI that uses low-level OS interfaces via golang.org/x/sys.
package main

import (
	"fmt"
	"os"

	"example.com/systool/internal/sys"
)

func main() {
	if err := run(); err != nil {
		fmt.Fprintln(os.Stderr, "systool:", err)
		os.Exit(1)
	}
}

func run() error {
	cols, rows, err := sys.TerminalSize(os.Stdout)
	if err != nil {
		return fmt.Errorf("terminal size: %w", err)
	}
	fmt.Printf("terminal: %dx%d\n", cols, rows)
	return nil
}
EOF
cat > internal/sys/sys.go <<'EOF'
// Package sys wraps platform-specific system calls behind a portable API.
//
// Implementations live in build-constrained files:
//   - sys_unix.go    (linux, darwin) using golang.org/x/sys/unix
//   - sys_windows.go (windows)       using golang.org/x/sys/windows
//   - sys_other.go   (everything else) returning ErrUnsupported
package sys

import "errors"

// ErrUnsupported is returned on platforms without an implementation.
var ErrUnsupported = errors.ErrUnsupported
EOF
cat > internal/sys/sys_unix.go <<'EOF'
//go:build linux || darwin

package sys

import (
	"os"

	"golang.org/x/sys/unix"
)

// TerminalSize returns the column and row count of the terminal attached to f.
func TerminalSize(f *os.File) (cols, rows int, err error) {
	ws, err := unix.IoctlGetWinsize(int(f.Fd()), unix.TIOCGWINSZ)
	if err != nil {
		return 0, 0, err
	}
	return int(ws.Col), int(ws.Row), nil
}
EOF
cat > internal/sys/sys_windows.go <<'EOF'
//go:build windows

package sys

import (
	"os"

	"golang.org/x/sys/windows"
)

// TerminalSize returns the column and row count of the console attached to f.
func TerminalSize(f *os.File) (cols, rows int, err error) {
	var info windows.ConsoleScreenBufferInfo
	if err := windows.GetConsoleScreenBufferInfo(windows.Handle(f.Fd()), &info); err != nil {
		return 0, 0, err
	}
	w := info.Window
	return int(w.Right-w.Left) + 1, int(w.Bottom-w.Top) + 1, nil
}
EOF
cat > internal/sys/sys_other.go <<'EOF'
//go:build !linux && !darwin && !windows

package sys

import "os"

// TerminalSize is not implemented on this platform.
func TerminalSize(f *os.File) (cols, rows int, err error) {
	return 0, 0, ErrUnsupported
}
EOF
cat > .gitignore <<'EOF'
/systool
/systool.exe
/dist/
EOF
go mod tidy && gofmt -l . ; go vet ./... && for t in linux/amd64 linux/arm64 darwin/amd64 darwin/arm64 windows/amd64 freebsd/amd64; do GOOS=${t%/*} GOARCH=${t#*/} go build -o /dev/null ./cmd/systool && echo "ok $t"; done; go run ./cmd/systool; cat go.mod

